llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "In healthy male volunteers, tofogliflozin given as a single 20 mg oral dose with a concomitant IV microdose showed a mean absolute bioavailability of 97.5%, directly demonstrating high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "A clinical study using a double tracer technique reported about 98% absolute oral bioavailability for tofogliflozin, with only 0.9% of parent drug in feces indicating complete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Following a single oral 20 mg dose of [14C]-tofogliflozin in Japanese healthy subjects, the drug exhibited favorable pharmacokinetics including high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct human absolute bioavailability data for tofogliflozin (97.5–98%) strongly support high oral bioavailability (F ≥ 20%). The mixed physicochemical prior is overridden by robust experimental evidence.",
  "evidence_gaps": [
    "No explicit fasted-state absolute bioavailability measurement for tofogliflozin was cited, but high absolute BA in humans is unlikely to be food-dependent.",
    "The query SMILES matches tofogliflozin; if not, the very high transfer score of the tofogliflozin evidence still supports the prediction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

